'Custom_SMS_Payload_Hint' => 'अनुरोध बॉडी के फ़ील्ड परिभाषित करें। प्लेसहोल्डर के रूप में {phone}, {message} और {sender} का उपयोग करें; भेजते समय इन्हें बदल दिया जाएगा।',
'Custom_SMS_Guide_Title' => 'कॉन्फ़िगर कैसे करें',
'Custom_SMS_Guide_Intro' => 'HTTP API वाला कोई भी SMS प्रदाता जोड़ा जा सकता है। अपने प्रदाता का API दस्तावेज़ खोलें, एंडपॉइंट, विधि और फ़ील्ड नाम कॉपी करें, फिर प्लेसहोल्डर का उपयोग करके उन्हें नीचे मैप करें।',
'Custom_SMS_Guide_Placeholder_Phone' => 'प्राप्तकर्ता का फ़ोन नंबर',
'Custom_SMS_Guide_Placeholder_Message' => 'SMS का पाठ',
'Custom_SMS_Guide_Placeholder_Sender' => 'ऊपर दर्ज किया गया प्रेषक आईडी',
'Custom_SMS_Guide_Api_Url' => 'आपके प्रदाता के दस्तावेज़ से पूरा एंडपॉइंट URL, जैसे https://api.provider.com/sms/send. प्लेसहोल्डर सीधे URL में भी लिखे जा सकते हैं, जैसे ...?to={phone}&text={message}.',
'Custom_SMS_Guide_Method' => 'POST सबसे सामान्य है। GET केवल तभी चुनें जब आपका प्रदाता सब कुछ URL में अपेक्षित करता हो — तब पेलोड फ़ील्ड क्वेरी पैरामीटर के रूप में भेजे जाते हैं।',
'Custom_SMS_Guide_Content_Type' => '"json" पेलोड को JSON बॉडी के रूप में भेजता है (application/json)। "form" इसे सामान्य HTML फ़ॉर्म के रूप में भेजता है (application/x-www-form-urlencoded)। जाँचें कि आपका प्रदाता कौन-सा अपेक्षित करता है; GET के लिए यह अनदेखा किया जाता है।',
'Custom_SMS_Guide_Sender' => 'आपका स्वीकृत प्रेषक आईडी या भेजने वाला फ़ोन नंबर। यह केवल {sender} प्लेसहोल्डर भरता है — भेजे जाने के लिए इसे पेलोड, हेडर या URL में उपयोग करना होगा।',
'Custom_SMS_Guide_Success_Keyword' => 'वैकल्पिक, परंतु अनुशंसित। कुछ प्रदाता भेजने में विफल होने पर भी "200 OK" उत्तर देते हैं। ऐसा शब्द या अंश दर्ज करें जो केवल सफल उत्तर में आता हो (जैसे success)। यदि उत्तर में वह न हो, तो SMS को विफल माना जाएगा।',
'Custom_SMS_Guide_Headers' => 'आपके प्रदाता द्वारा आवश्यक प्रमाणीकरण हेडर, जैसे Authorization = Bearer YOUR_API_KEY, या Api-Key = YOUR_API_KEY. Content-Type न जोड़ें — यह स्वतः सेट हो जाता है।',
'Custom_SMS_Guide_Payload' => 'अनुरोध बॉडी के फ़ील्ड, ठीक उन्हीं नामों से जैसे आपके प्रदाता के दस्तावेज़ में हैं। मान के रूप में प्लेसहोल्डर उपयोग करें, जैसे to = {phone}, message = {message}, from = {sender}.',
'Custom_SMS_Guide_Example' => 'पूरा उदाहरण',
'Custom_SMS_Guide_Default_Note' => 'सहेजने के बाद इस पृष्ठ के ऊपर डिफ़ॉल्ट SMS गेटवे के रूप में "custom" चुनें और सबमिट करें — अन्यथा SMS पहले चुने गए गेटवे का ही उपयोग करता रहेगा।',
