'OfflinePayments' => 'ऑफ़लाइन भुगतान',
'OfflinePaymentsIntro' => 'सिस्टम के बाहर किया गया हर भुगतान यहाँ रहता है: डिलीवरी पर नकद, मोबाइल भुगतान, GCash, बैंक हस्तांतरण और लेने पर नकद। जब तक आप इन्हें भुगतान हुआ चिह्नित नहीं करते, ये ऑर्डर भुगतान-लंबित रहते हैं। GCash और बैंक हस्तांतरण ग्राहक से स्क्रीनशॉट, संदर्भ संख्या और राशि माँगते हैं, जिन्हें आप ऑर्डर पर स्वीकृत करते हैं।',
'Online_Store' => 'ऑनलाइन दुकान',
'Online_Store_Enabled_Help' => 'अक्षम होने पर ऑनलाइन दुकान के पृष्ठ पहुँच से बाहर हो जाएँगे।',
'Ord_Guide_Intro' => 'आपकी ऑनलाइन दुकान पर दिया गया ऑर्डर कैसे आपके स्टॉक और खातों तक पहुँचता है, और पैसा वास्तव में कहाँ दर्ज होता है।',
'Ord_Guide_Lifecycle_Title' => 'ऑर्डर की स्थिति',
'Ord_Guide_MarkPaid_Note' => 'यहाँ दिखाई गई भुगतान स्थिति चेकआउट पर किए गए चयन को ही दर्ज रखती है और अपरिवर्तित रहती है। लेखा रिकॉर्ड बिक्री है, और वही आपकी भुगतान और लाभ रिपोर्ट को भरती है। आपने जो दर्ज किया उसे देखने या संपादित करने के लिए बिक्री पर "भुगतान दिखाएँ" का उपयोग करें।',
'Ord_Guide_MarkPaid_Title' => 'भुगतान को लंबित से भुगतान हुआ में बदलना',
'Ord_Guide_Notes_Title' => 'जानने योग्य बातें',
'Ord_Guide_PaymentStatus_Tip' => 'चेकआउट पर निर्धारित होती है और यहाँ संपादित नहीं की जा सकती। भुगतान कैसे दर्ज करें, यह देखने के लिए क्लिक करें।',
'Ord_Guide_Payment_Failed' => 'गेटवे ने भुगतान अस्वीकार कर दिया या ग्राहक ने उसे छोड़ दिया। ऑर्डर स्वतः रद्द हो जाता है।',
'Ord_Guide_Payment_Intro' => 'यह कॉलम दर्ज करता है कि ग्राहक ने चेकआउट पर भुगतान का कौन-सा तरीका चुना। यह स्टोरफ्रंट द्वारा निर्धारित होता है और इस पृष्ठ से संपादित नहीं किया जा सकता — पैसा स्वयं उस बिक्री पर ट्रैक होता है जो ऑर्डर की पुष्टि करने पर बनती है।',
'Ord_Guide_Payment_Paid' => 'ग्राहक पहले ही भुगतान गेटवे से ऑनलाइन भुगतान कर चुका है। ऑर्डर की पुष्टि करने पर बिक्री "भुगतान हुआ" के रूप में बनती है और भुगतान भी दर्ज हो जाता है — और कुछ करने की आवश्यकता नहीं।',
'Ord_Guide_Payment_Pending' => 'डिलीवरी पर नकद, बैंक हस्तांतरण या कोई अन्य बाद-में-भुगतान वाला तरीका। ऑर्डर की पुष्टि करने पर बिक्री "अदत्त" के रूप में बनती है, इसलिए पैसा मिलने पर आप उसे स्वयं दर्ज करते हैं — नीचे दिए चरण देखें।',
