'Ord_Guide_Lifecycle_Shipped' => 'आपने ऑर्डर भेज दिया। यह केवल पूर्ति है: स्टॉक तो पुष्टि के समय ही घट चुका था।',
'Ord_Guide_MarkPaid_Step1' => 'पहले यहाँ ऑर्डर की पुष्टि करें — पुष्टि करने से ही बिक्री बनती है।',
