'Ord_Guide_MarkPaid_Step3' => 'पंक्ति का कार्य मेनू खोलें और "भुगतान बनाएँ" चुनें।',
'Ord_Guide_MarkPaid_Step4' => 'राशि, भुगतान विधि और तिथि दर्ज करके सहेजें। राशि के अनुसार बिक्री स्वयं "आंशिक" या "भुगतान हुआ" में बदल जाती है।',
'Ord_Guide_Note_Cancel' => 'रद्दीकरण केवल तभी संभव है जब ऑर्डर अभी लंबित हो। पुष्टि हो जाने के बाद उसे बिक्री या ग्राहक वापसी के माध्यम से उलटें।',
'Ord_Guide_Note_Flagged' => '"चिह्नित" टैग का अर्थ है कि चेकआउट पर ऑर्डर किसी धोखाधड़ी जाँच में अटका। कारण देखने के लिए टैग पर माउस ले जाएँ और पुष्टि से पहले ऑर्डर की समीक्षा करें।',
'Ord_Guide_Note_Preorder' => 'प्री-ऑर्डर आइटम स्टॉक जाँच छोड़ देते हैं, इसलिए उन्हें शामिल करने वाला ऑर्डर तब भी पुष्ट किया जा सकता है जब मात्रा अभी उपलब्ध न हो।',
'Ord_Guide_Note_Warehouse' => 'पुष्टि करते समय आप जो गोदाम चुनते हैं, वही तय करता है कि स्टॉक कहाँ से लिया जाएगा। जो गोदाम पूरा ऑर्डर पूरा नहीं कर सकते, वे उस सूची में "स्टॉक में नहीं" चिह्नित होते हैं।',
